SELECT count(*) AS qa_reference_rows FROM mes.rm_qa_reference_stage;
SELECT quality_level,count(*) AS rows FROM mes.rm_qa_reference_stage GROUP BY quality_level ORDER BY quality_level;
SELECT
  count(*) FILTER (WHERE NULLIF(BTRIM(heat_no),'') IS NOT NULL) AS rows_with_heat_no,
  count(*) FILTER (WHERE NULLIF(BTRIM(hr_grade),'') IS NOT NULL) AS rows_with_steel_grade,
  count(*) FILTER (WHERE NULLIF(BTRIM(vendor_grade),'') IS NOT NULL) AS rows_with_vendor_grade
FROM mes.rm_qa_reference_stage;